index e60fb80..f4f0cc9 100644
--- a/src/transport/ws/validation.test.ts
+++ b/src/transport/ws/validation.test.ts
@@ -20,4 +20,42 @@ describe('the websocket frame validator', () => {

     expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
   });
+
+  it('validates list_sessions frames, forwarding optional limit and before while dropping unknown fields', () => {
+    const bare = validateMessage({type: 'list_sessions'});
+    const withOptions = validateMessage({
+      type: 'list_sessions',
+      limit: 10,
+      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
+      userId: 'u2',
+      extra: true,
+    });
+    const badFrames = [
+      {type: 'list_sessions', limit: 'ten'},
+      {type: 'list_sessions', limit: -1},
+      {type: 'list_sessions', limit: 1.5},
+      {type: 'list_sessions', before: 'not-an-object'},
+      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
+      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
+      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
+      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
+    ];
+
+    expect({
+      bare,
+      withOptions,
+      badResults: badFrames.map(frame => validateMessage(frame).valid),
+    }).toEqual({
+      bare: {valid: true, data: {type: 'list_sessions'}},
+      withOptions: {
+        valid: true,
+        data: {
+          type: 'list_sessions',
+          limit: 10,
+          before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
+        },
+      },
+      badResults: Array(badFrames.length).fill(false),
+    });
+  });
 });
diff --git a/src/transport/ws/validation.ts b/src/transport/ws/validation.ts
